const items = $input.all();
const results = [];

for (const item of items) {
  const payload = item.json.body || item.json;

  const workflowName = payload.workflow_name || payload.workflow || 'notification-system';
  const eventId = payload.event_id || payload.eventId || `err_${Date.now()}`;
  const recipient = payload.recipient || payload.to || 'unknown-recipient';
  const template = payload.template || payload.template_name || 'unknown-template';
  const errorCode = payload.error_code || payload.errorCode || payload.status || 'NOTIFICATION_DELIVERY_FAILED';
  const errorMessage = payload.error_message || payload.errorMessage || payload.error || payload.message || 'WhatsApp Cloud API retry limit exceeded';
  const tenantId = payload.tenant_id || payload.tenantId || 'default-tenant';
  const correlationId = payload.correlation_id || payload.correlationId || `corr_${Date.now()}`;
  const timestamp = payload.timestamp || new Date().toISOString();

  results.push({
    json: {
      eventType: 'notification.delivery_failed',
      alertType: 'notification_failure',
      severity: 'high',
      workflow: workflowName,
      workflowName,
      eventId,
      recipient,
      template,
      errorCode,
      errorMessage,
      errorDetails: errorMessage,
      tenantId,
      correlationId,
      timestamp,
      adminAlertSummary: `[CRITICAL ALERT] Notification failure in workflow '${workflowName}' for recipient ${recipient} using template '${template}': ${errorMessage}`
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const res = item.json;
  // Check if httpRequest succeeded (returns 2xx body)
  const isAcknowledged = Boolean(res.success === true || res.message === 'Callback received' || (res.statusCode >= 200 && res.statusCode < 300));

  if (isAcknowledged) {
    results.push({
      json: {
        success: true,
        status: 'alert_dispatched',
        acknowledged: true,
        acknowledgedBy: 'backend-n8n-callback',
        alertSummary: res.adminAlertSummary || 'Notification failure acknowledged by admin backend',
        eventId: res.eventId,
        tenantId: res.tenantId,
        dispatchedAt: new Date().toISOString()
      }
    });
  } else {
    results.push({
      json: {
        success: false,
        status: 'alert_delivery_failed',
        acknowledged: false,
        error: res.error || res.message || 'Failed to deliver failure alert to Admin Notification Panel (HTTP error)',
        eventId: res.eventId,
        tenantId: res.tenantId,
        failedAt: new Date().toISOString()
      }
    });
  }
}

return results;
